/// <summary>
/// PricingAttribute of table <c>CustBankAccount</c> field SWIFTNo.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeCustBankAccountSWIFTNo extends GUPPricingAttributeCustBankAccount implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustBankAccount, SWIFTNo);
}

    public Set getAllowedValues()
    {
        var             ret = new Set(Types::String);
        CustBankAccount custBankAccount;

        while select custBankAccount
            group by SWIFTNo
        {
            if (! ret.in(custBankAccount.SWIFTNo))
            {
                ret.add(custBankAccount.SWIFTNo);
            }
        }
        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(CustBankAccount, SWIFTNo));
        qbr.value(queryValue(_value));
    }
